const flatCategories = $input.first().json.categories.category;

// 1. Отримаємо всі parentID — тобто ті, що мають дітей
const parentIDs = new Set(flatCategories.map(cat => cat.parentID));

// 2. Фільтруємо лише кінцеві категорії (які самі не є parent'ами)
const leafCategories = flatCategories.filter(cat => !parentIDs.has(cat.categoryID));

// 3. Побудова повного шляху для кожної leaf-категорії
function getFullPath(category, map) {
  const path = [category.categoryName];
  let current = map.get(category.parentID);
  while (current && current.categoryID !== current.parentID) {
    path.unshift(current.categoryName);
    current = map.get(current.parentID);
  }
  if (current) path.unshift(current.categoryName); // додаємо root
  return path.join('/');
}

// 4. Створюємо Map для швидкого доступу по ID
const catMap = new Map(flatCategories.map(cat => [cat.categoryID, cat]));

// 5. Повертаємо результат
return leafCategories.map(cat => ({
  categoryID: cat.categoryID,
  full_path: getFullPath(cat, catMap)
}));

