function slugify(text) {
  return text
    .replace(/\\/g, "")                        
    .replace(/["'“”„‟″‶‷]/g, "")
    .replace(/[()]/g, "")
    .replace(/[-–—−]/g, "")
    .replace(/,/g, "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/--+/g, "-");
}

const slug = slugify(rawName);

